{
  "root_cause": "The datepicker component updates the input value to a locale-formatted string during initialization, even when the user hasn't selected a date. This causes the submitted departure date to change from the ISO format (YYYY-MM-DD) to a locale-specific format (e.g., MM/DD/YYYY) when the datepicker is opened and closed without selecting a date.",
  "repair_strategy": "Add a flag `_isInitializing` to prevent updating the main input value during initialization while still allowing updates to bound inputs and display elements. The flag is set to true at the start of `_initCalendar` and false at the end. In `_syncSelectedDates`, the main input value is only updated if the flag is false.",
  "edits": [
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "  protected declare _element: HTMLElement & { value: string }
  protected declare _config: DatepickerConfig
  protected declare _calendar: Calendar | null
  protected declare _isShown: boolean
  protected declare _isInput: boolean
  protected declare _isInline: boolean
  protected declare _boundInput: HTMLInputElement | null
  protected declare _positionElement: HTMLElement
  protected declare _displayElement: HTMLElement | false | null
  protected declare _themeObserver: MutationObserver | null
  protected declare _themeAncestor: Element | null | undefined
  protected declare _onOutside: (event: Event) => void
  protected declare _onTriggerClick: () => void",
      "after": "  protected declare _element: HTMLElement & { value: string }
  protected declare _config: DatepickerConfig
  protected declare _calendar: Calendar | null
  protected declare _isShown: boolean
  protected declare _isInput: boolean
  protected declare _isInline: boolean
  protected declare _boundInput: HTMLInputElement | null
  protected declare _positionElement: HTMLElement
  protected declare _displayElement: HTMLElement | false | null
  protected declare _themeObserver: MutationObserver | null
  protected declare _themeAncestor: Element | null | undefined
  protected declare _onOutside: (event: Event) => void
  protected declare _onTriggerClick: () => void
  protected declare _isInitializing: boolean"
    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "    constructor(element?: string | Element | null, config?: Partial<DatepickerConfig> | null) {
      super(element, config)

      this._calendar = null
      this._isShown = false

      this._initCalendar()
    }",
      "after": "    constructor(element?: string | Element | null, config?: Partial<DatepickerConfig> | null) {
      super(element, config)

      this._calendar = null
      this._isShown = false
      this._isInitializing = false

      this._initCalendar()
    }"
    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "  protected _initCalendar(): void {
    this._isInput = this._element.tagName === 'INPUT'
    this._isInline = this._config.inline",
      "after": "  protected _initCalendar(): void {
    this._isInitializing = true
    this._isInput = this._element.tagName === 'INPUT'
    this._isInline = this._config.inline"
    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "    // Populate input/display with preselected dates
    this._updateDisplayWithSelectedDates()
  }",
      "after": "    // Populate input/display with preselected dates
    this._updateDisplayWithSelectedDates()
    this._isInitializing = false
  }"
    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "  protected _syncSelectedDates(selectedDates: string[]): void {
    const formattedDate = this._formatDateForInput(selectedDates)
    if (this._isInput) {
      this._element.value = formattedDate
    }

    if (this._boundInput) {
      this._boundInput.value = selectedDates.join(',')
    }

    if (this._displayElement) {
      this._displayElement.textContent = formattedDate
    }
  }",
      "after": "  protected _syncSelectedDates(selectedDates: string[]): void {
    const formattedDate = this._formatDateForInput(selectedDates)
    if (this._isInput && !this._isInitializing) {
      this._element.value = formattedDate
    }

    if (this._boundInput) {
      this._boundInput.value = selectedDates.join(',')
    }

    if (this._displayElement) {
      this._displayElement.textContent = formattedDate
    }
  }"
    }
  ],
  "expected_accessibility_effect": "The datepicker will no longer modify the input value during initialization, preserving the original format. Users relying on assistive technologies will perceive the input value as unchanged when opening and closing the datepicker without selecting a date, reducing confusion.",
  "functional_risks": [
    "The bound input and display element will still be updated during initialization, which is expected.",
    "Programmatic use of setSelectedDates will continue to update the main input as intended.",
    "Inline datepickers may experience delayed input updates until user interaction, but the calendar will still reflect the correct selected state."
  ],
  "verification_requirements": [
    "Verify that the departure date remains in ISO format (YYYY-MM-DD) after opening and closing the datepicker without selecting a date.",
    "Verify that selecting a date updates the input to the locale-formatted string.",
    "Verify that the bound input and display element update correctly during initialization and interaction.",
    "Verify that keyboard navigation (Tab, Escape, Enter) functions as expected in the journey."
  ]
}
